on conflict (source, source_id) where source_id is not null do update set name = excluded.name, category = excluded.category, kcal_100g = excluded.kcal_100g, protein_100g = excluded.protein_100g, carbs_100g = excluded.carbs_100g, fat_100g = excluded.fat_100g, sugar_100g = excluded.sugar_100g, fiber_100g = excluded.fiber_100g, sat_fat_100g = excluded.sat_fat_100g, salt_100g = excluded.salt_100g, density = excluded.density, unit_grams = excluded.unit_grams, food_category = excluded.food_category, aliases = excluded.aliases, kind = excluded.kind, is_vegetarian = excluded.is_vegetarian, is_vegan = excluded.is_vegan, source_category = excluded.source_category, is_hidden = excluded.is_hidden;
